'figeac|2021':{blend:{ME:29,CF:31,CS:40},yld:40,window:'Unlike in the past, even the very young vintages are a pleasure to drink.',wtl:1,url:'https://www.chateau-figeac.com/millesime/millesime-2021/',src:'CHATEAU-FIGEAC-Datasheet-March-2021.pdf',months:'15-18'},
'figeac|2022':{blend:{ME:35,CF:34,CS:31},url:'https://www.chateau-figeac.com/millesime/millesime-2022/',src:'2022__-the-2022-classification-of-the-grands-crus-of-saint-emilion.txt'},
'giscours|2021':{blend:{CS:56,ME:44},url:'https://giscours.com/fr/2021/08/16/rose-x-giscours-2020-la-nouvelle-signature-du-chateau-giscours/',src:'2021__07-02-millesime-2020-du-chateau-giscours-precision-et-audace.txt'},
'gruaud-larose|2019':{blend:{CS:72,ME:25,CF:3},taste:'Two threatening frost episodes in April in the end had very little effect on the Gruaud vineyard, which benefited from its closeness to the Gironde.',src:'chateau-gruaud-larose-2019-fr.pdf',ttl:1,alc:13.65,oak:80,months:'18'},
'gruaud-larose|2022':{blend:{CS:83,ME:14,CF:3},harvest:'7 Septembre',pick:{ALL:'09-07|'},note:'Coming out of a mild and moderately wet winter, the Merlot parcels at the foot of the rises were exposed to a serious frost episode during the first ten days of April.',src:'Chateau-Gruaud-Larose-2022-FR.pdf',ntl:1,alc:13.64,months:'18',oak:95},
'gruaud-larose|2023':{blend:{CS:83,ME:14.5,CF:2.5},note:'Through the winter the cover crops are grazed by a flock of 300 ewes.',src:'Chateau-Gruaud-Larose-2023-FR.pdf',ntl:1,alc:12.62,months:'18',oak:95},
'gruaud-larose|2024':{blend:{CS:81,ME:17,CF:2},harvest:'27 septembre',ph:3.77,src:'Chateau-Gruaud-Larose-2024-FR.pdf',alc:12.39,months:'18',oak:95,pick:{ALL:'09-27|'},note:'L’hiver 2023-2024 restera marqué par des pluies records et une douceur des températures entraînant un débourrement très précoce. Le printemps a été frais et particulièrement humide.'},
'guiraud|2022':{blend:{SEM:65,SB:35},harvest:'15 septembre',yld:10,ph:4.01,window:'A very long finish, pointing to this wine’s fine keeping potential.',wtl:1,pick:{ALL:'09-15|'},note:'After a mild winter, the 2022 growing season began very early.',taste:'A very long finish, promising fine ageing potential for this wine.',src:'cha-teau-guiraud-1er-grand-cru-classe-en-1855-2022.pdf',ttl:1,ntl:1,oak:10,months:'18',press:{'Falstaff':'95','James Suckling':'96'}},
'guiraud|2023':{blend:{SEM:60,SB:40},harvest:'24 août',yld:30,ph:3.4,pick:{ALL:'08-24|'},note:'A warm vintage on the whole, with very contrasting rainfall. After a frost episode at the very start of April, the vine\'s growth began in ideal conditions: warmth and regular rainy spells produced an exuberant canopy that called for all our growers\' commitment and expertise to keep in check.',src:'g-de-chateau-guiraud-2023_fr.pdf',ntl:1,months:'6'},
