'siaurac|2013':{blend:{ME:75,CF:15,MA:10},alc:13.5,yld:45,months:'12-14',press:{'Wine Spectator':'86-89'},src:'FT_Siaurac_2013_FR.pdf'},
'siaurac|2014':{blend:{ME:80,CF:15,MA:5},alc:13.5,yld:51,months:'12-14',src:'FT_Siaurac_2014_FR.pdf'},
'siaurac|2015':{blend:{ME:80,CF:15,MA:5},alc:14,yld:30,months:'12-14',src:'FT_Siaurac_2015_FR.pdf'},
'siaurac|2016':{blend:{ME:74,CF:19,MA:7},alc:14,yld:55,months:'12-14',src:'FT_Siaurac_2016_FR.pdf',taste:'ARY of Jean-Claude BERROUET : Fresh tannins, notes of peppermint, very original mineral character, a wine that is sure to keep for a very long time for very long cellaring.'},
'siaurac|2017':{blend:{ME:63,CF:17,MA:20},alc:14,yld:5.3,months:'14',oak:85,src:'FT_Siaurac_2017_FR.pdf',pick:{ALL:'09-22|10-20'},taste:'Robe rouge violacée, limpide et profonde. Nez intense et complexe dégageant des notes de petits fruits noirs, léger fumé, vanillées, avec des pointes épicées et poivrés. Bouche gourmande et fraiche, avec une attaque franche et un bon volume en bouche. Finale soyeuse.'},
'siaurac|2018':{blend:{ME:80,CF:20},yld:45,months:'14',press:{'James Suckling':'91','Yves Beck':'91'},src:'Fiche-Technique-Chateau-Siaurac-2018.pdf',pick:{ALL:'09-14|10-11'},taste:'Un rouge doux et attrayant avec des notes de prune et de chocolat, ainsi que des nuances d\'épices et de noisettes. Il est moyennement corsé, avec des tanins moyennement ronds et une finale fraîche et savoureuse. A boire ou à garder.'},
'siaurac|2019':{blend:{ME:80,CF:20},yld:29,months:'14',press:{'James Suckling':'91'},src:'Fiche-Technique-Chateau-Siaurac-2019-Lalande-de-Pomerol.pdf',taste:'Bouquet intense et complexe développant des notes de petits fruits noirs et d\'épices.'},
