'bourgeois-chateau-bellegrave|2019':{blend:{CS:66,ME:34},yld:54,months:'12',src:'Fiche_Technique_CHATEAU_BELLEGRAVE_PAU_RO_2019_Francais_et_Anglais.pdf',via:'trade',pick:{ALL:'09-20|10-07'}},
'bourgeois-chateau-bellegrave|2020':{blend:{CS:60,ME:40},yld:40,months:'12',oak:40,src:'Fiche_Technique_2020_Bellegrave-Anglais.pdf',via:'trade',alc:14.5},
'bourgeois-chateau-bellegrave|2021':{blend:{CS:75,ME:25},yld:42,months:'12',oak:35,src:'Ch.-Bellegrave-2021-EN.pdf',via:'trade',alc:13,note:'Predominantly made from Cabernet Sauvignon, with a more traditional balance between alcohol and acidity, our wines are incredibly elegant and harmonious.” Ludovic & Julien Meffre - April 2022 CHÂTEAU BELLEGRAVE 2021 Harvest dates : September 28 th to October 7th 2021 Blend : 75% Cabernet Sauvignon, 25% Merlot Maturing : 12 months aging, 35% new'},
'bourgeois-chateau-bellegrave|2022':{blend:{CS:60,ME:40},yld:37,months:'12',oak:35,src:'Ch.-Bellegrave-2022-EN.pdf',via:'trade',alc:15},
'bourgeois-chateau-bellegrave|2023':{blend:{CS:60,ME:40},alc:13.5,yld:55,months:'12',src:'Bellegrave-2023-FT-FR-Primeurs.pdf',via:'trade',oak:35,pick:{ALL:'09-09|09-26'}},
'bourgeois-chateau-bellegrave|2024':{blend:{CS:60,ME:40},alc:12.5,yld:35,months:'12',src:'ft_bellegrave-2024_bellegrave-2024-ft-fr-primeurs.pdf',via:'trade',note:'2024 was marked by demanding weather, which influenced every stage of the vine\'s cycle. Thanks to our expertise and heightened vigilance, however, we were able to turn those challenges into opportunities, giving rise to wines of a great finesse and a fine balance, all the more precious in that their production proves very limited this year. Exceptionally high rainfall, together with milder temperatures than normal, certainly disturbed the vine\'s early development. That abundance of water nevertheless made a precious reserve, favouring vigorous and even growth from the start of the season.',oak:35,pick:{ALL:'09-24|10-04'}},
