'du-tertre|2020':{blend:{CS:47,ME:24,CF:21,PV:8},months:'12',oak:40,src:'Fiche_technique_Chateau_DU_TERTRE_MAR_RO_2020.pdf',via:'trade',pick:{ALL:'09-14|'}},
'du-tertre|2023':{blend:{CS:70,ME:15,CF:11,PV:4},months:'14-16',oak:60,src:'FT-CHATEAU-DU-TERTRE-2023-ANG.pdf',via:'trade'},
'du-tertre|2024':{blend:{CS:75,ME:13,CF:10,PV:2},months:'16',oak:60,src:'FT_CHATEAU_DU_TERTRE_2024-ANG.pdf',via:'trade',taste:'First impressions are of dark fruits, subtle smoke and notes of raw cocoa. The bouquet is sophisticated and complex. The palate is bold and dense, supported by an impressive acidity and great length. The nobility of the Cabernet Sauvignon provides a purity of fruit and a licorice freshness. The tannins, elegant and soft, are equally an expression of this blend in which each variety leaves its footprint.'},
'durfort-vivens|2019':{yld:50,months:'18',src:'Chateau-Durfort-Vivens-2019-EN.pdf',via:'trade',oak:60},
