'leoville-barton|2012':{blend:{CS:83,ME:15,CF:2},src:'Leoville-Barton-2012-FT-FR-65.pdf',via:'trade',oak:60},
'leoville-barton|2013':{blend:{CS:85,ME:15},alc:13,yld:35,months:'18',oak:60,src:'Leoville-Barton-2013-FT-FR-65.pdf',via:'trade'},
'leoville-barton|2015':{blend:{CS:86,ME:14},src:'Leoville-Barton-2015-FT-FR-65.pdf',via:'trade',alc:13,oak:60},
'leoville-barton|2016':{blend:{CS:86,ME:14},src:'Leoville-Barton-2016-FT-FR-65.pdf',via:'trade',alc:13,oak:60},
'leoville-barton|2017':{blend:{CS:93,ME:7},src:'Leoville-Barton-2017-FT-FR.pdf',via:'trade',alc:13,oak:60},
'leoville-barton|2018':{blend:{CS:82,ME:18},src:'Leoville-Barton-2018-FT-FRGB.pdf',via:'trade',oak:60},
'leoville-barton|2020':{blend:{CS:85.5,ME:14.5},yld:34,src:'Chateau-Leoville-Barton-Primeurs-2020.pdf',via:'trade',alc:13.6,oak:60,taste:'Robe intense de couleur pourpre. Le nez est complexe révélant des arômes de fruits noirs, de groseille et de cassis. En bouche, le vin est onctueux et juteux, subtilement épicé. Il dévoile des notes de framboise et de prune d’ente avec une acidité élégante. Intense purple color. The nose is complex revealing aromas of black fruits, currant and blackcurrant. On the palate, the wine is incredible smooth and juicy, subtly spicy.'},
'leoville-barton|2021':{blend:{CS:84,ME:11,CF:5},src:'Chateau-Leoville-Barton-Primeurs-2021.pdf',via:'trade',oak:60,pick:{ALL:'09-27|10-07'}},
'leoville-barton|2022':{blend:{CS:83,ME:11.5,CF:5.5},yld:30,src:'Chateau-Leoville-Barton-Primeurs-2022.pdf',via:'trade',alc:14.1,oak:60},
'leoville-barton|2023':{blend:{CS:87,ME:10,CF:3},src:'Chateau-Leoville-Barton-Primeurs-2023.pdf',via:'trade',alc:13,oak:60},
'leoville-barton|2024':{blend:{CS:92,ME:6,CF:2},src:'Chateau-Leoville-Barton-Primeurs-2024.pdf',via:'trade',alc:12.9,oak:60},
'leoville-barton|2025':{blend:{CS:86,ME:12,CF:2},src:'FT-_Chateau-Leoville-Barton-Primeurs-2025.pdf',via:'trade',alc:13.5,oak:60},
