'stem-chateau-soutard|2021':{blend:{CS:7,ME:70,CF:18,MA:5},alc:13,src:'Soutard_2021_FT_GB-1.pdf',via:'trade',oak:45},
'stem-chateau-soutard|2022':{blend:{CS:8,ME:76,CF:10,MA:6},alc:14,src:'ft_soutard-2022_soutard-2022-ft-gb.pdf',via:'trade',oak:50},
'stem-chateau-soutard|2024':{blend:{CS:13,ME:48,CF:32,MA:7},press:{'James Suckling':'91-92','Wine Advocate':'91-93','Yves Beck':'94-96'},src:'ft_soutard-2024_soutard-2024-primeurs-fr.pdf',via:'trade',note:'The oceanic climate in all its splendour. 2024 reveals the great terroirs and demands perfect technical control. 2024 is a year with a water surplus of more than 60% against the ten-year average. Since 10 October 2023, regular rain has rebuilt the available water reserves and badly disturbed outside work except in the summer months. The autumn and winter were very mild, the spring and summer rather cool. Those conditions allowed us to make wines that are fruity, aromatically intense and sapid. All the art in the cellar was in releasing the structure and the aromas of the fruit with precision, respect and delicacy.',oak:50,pick:{ALL:'09-19|10-07'}},
