'marquis-de-terme|2018':{blend:{CS:60,ME:35,PV:5},note:'A contrasting winter gave way to a spring as mild as it was wet. The exceptional sunshine and heat of July and August dried out the soils and created the water stress that favours quality.',ntl:1,src:'Marquis-de-Terme-2018-FT-FR.pdf',pick:{ALL:'09-26|10-02'}},
